   const row={nome:d.nome,responsavel:d.responsavel,sobrenome:d.sobrenome,whatsapp:nt(d.whatsapp),endereco:adrTxt({rua:d.rua,num:d.num,comp:d.comp}),rua:d.rua,numero:d.num,complemento:d.comp||null,referencia:d.ref,bairro:d.bairro,cidade:d.cidade,cep:cepD(d.cep),uf:'BA',categoria:d.categoria||null,perfil:d.perfil==='autonomo'?'autonomo':'loja',indic_cod:String(d.indic_cod||'').trim().toUpperCase().slice(0,12)||null,horario:d.horario||'{}',logo:logo,aceite_em:new Date().toISOString(),email:d.email};
