async function adm2fa(){const ok=await sb.rpc('admin_2fa_ok');if(ok.data===true)return;
 const pedir=async()=>{const r=await sb.rpc('admin_2fa_pedir');if(r.error)throw new Error(r.error.message)};
 await pedir();let msg='🔐 Confirmação de segurança\nEnviamos um código de 6 números para o e-mail da administração. Digite o código abaixo.\n(Para receber outro código, escreva: novo)';
 for(;;){const v=await dlg({msg,input:true,type:'tel',ph:'Código de 6 números',ok:'Confirmar',no:'Cancelar'});
  if(v===null){await sb.auth.signOut();throw new Error('Entrada da administração cancelada.')}
  const c=String(v).trim();
  if(/^novo$/i.test(c)){try{await pedir();msg='Enviamos um código novo. Digite abaixo:'}catch(x){msg=x.message+'\nDigite o último código recebido:'}continue}
  const r=await sb.rpc('admin_2fa_checar',{p_codigo:c});
  if(!r.error&&r.data===true)return;
  msg=(r.error&&r.error.message||'Código incorreto.')+'\nTente de novo (ou escreva: novo).'}}
