function envH(p){if(!p.envio)return '';const pago=p.pagamento!=='mp'||p.pg_status==='pago',pd=(LJA&&LJA.postagem_dias)||2,trk=c=>'https://melhorrastreio.com.br/rastreio/'+encodeURIComponent(c),me=p.me_status,id=p.id;
 let h='<div class="envl">📦 Enviar por: <b>'+esc(p.envio)+'</b> · '+brl(p.frete)+(p.envio_prazo?' · cliente espera em até '+p.envio_prazo+' dias úteis':'');
 if(p.rastreio)h+='<div class="envr">✅ Postado · código <b>'+esc(p.rastreio)+'</b> · <a class="lk" href="'+trk(p.rastreio)+'" target="_blank" rel="noopener">Acompanhar</a>'+(p.status==='saiu'&&me!=='gerada'?' · <button type="button" class="lk" onclick="envCorr('+id+')">Corrigir código</button>':'')+'</div>'+(me==='gerada'&&p.status==='saiu'?'<small class="hint" style="display:block">O rastreio é acompanhado sozinho: quando os Correios entregarem, o pedido muda para Entregue e o cliente é avisado.</small>':'')+'<div id="envf'+id+'"></div>';
 else if(!pago)h+='<small class="hint" style="display:block">Aguardando o pagamento do cliente. Depois de pago, poste em até '+pd+' dias úteis.</small>';
 else if(p.status==='confirmado'){
  if(me==='gerada')h+='<div class="envr">🏷️ <b>Etiqueta pronta</b>'+(p.me_tracking?' · código '+esc(p.me_tracking):'')+'</div><small class="hint" style="display:block">Imprima, cole no pacote e leve aos Correios em até '+pd+' dias úteis. Quando os Correios registrarem a postagem, o pedido muda para <b>Enviado</b> sozinho e o cliente recebe o código de rastreio.</small><div class="envb"><button type="button" class="btn s" onclick="meImp('+id+')">🖨️ Imprimir etiqueta</button><button type="button" class="btn s r" onclick="meCanc('+id+')">Cancelar etiqueta</button></div><button type="button" class="lk" onclick="meAtual(this)">🔄 Já postei: atualizar agora</button>';
  else{const pend=me==='carrinho'||me==='pago';h+='<small class="hint" style="display:block">Poste em até '+pd+' dias úteis. Gere a etiqueta aqui mesmo: o valor sai do saldo da sua conta no Melhor Envio e o rastreio fica automático.</small><div class="envb"><button type="button" class="btn s" onclick="meGerar('+id+',this)">🏷️ '+(pend?'Concluir etiqueta':'Gerar etiqueta')+'</button>'+(pend?'<button type="button" class="btn s r" onclick="meCanc('+id+')">Cancelar</button>':'')+'</div><details class="envm"><summary>Prefiro fazer manual (site do Melhor Envio ou balcão dos Correios)</summary><div class="envb"><button type="button" class="btn s" onclick="envCopiar('+id+')">📋 Copiar dados para a etiqueta</button><a class="btn s" href="https://app.melhorenvio.com.br" target="_blank" rel="noopener">Abrir o Melhor Envio ↗</a></div>'+envForm(id)+'</details>'}
 }
 return h+'</div>'}
