const MEMSG={ok:'✓ Conta do Melhor Envio conectada! Já dá para gerar etiquetas nos pedidos.',cancelado:'Conexão cancelada no Melhor Envio.',expirado:'O link de conexão expirou. Toque em Conectar de novo.',config:'Etiquetas ainda não configuradas. Fale com o suporte.',erro:'Não foi possível conectar ao Melhor Envio. Tente de novo.'};
const docF=v=>{const d=String(v||'').replace(/\D/g,'').slice(0,14);return d.length>11?d.replace(/^(\d{2})(\d{3})(\d{3})(\d{4})(\d{0,2}).*/,'$1.$2.$3/$4-$5'):d.length>9?d.replace(/^(\d{3})(\d{3})(\d{3})(\d{0,2}).*/,'$1.$2.$3-$4'):d};
