async function meInit(){const e=$('meBox');if(!e)return;const l=LJA||{},T='<b class="ecs">🏷️ Etiquetas (Melhor Envio)</b>';
 if(MERET){const m=MERET;MERET=null;toast(MEMSG[m]||MEMSG.erro);setTimeout(()=>{sub('cfe');e.scrollIntoView({block:'center'})},300)}
 const rem='<details class="medet"><summary>Dados da etiqueta (remetente)</summary><label>Nome ou razão social<input id="remN" maxlength="60" value="'+esc(l.rem_nome||l.nome||'')+'"></label><label>CPF ou CNPJ<input id="remD" inputmode="numeric" maxlength="18" autocomplete="off" oninput="docM(this)" value="'+esc(docF(l.rem_doc))+'"></label><label>Telefone<input id="remT" type="tel" inputmode="numeric" maxlength="15" oninput="telM(this)" value="'+esc(fone(l.rem_tel||l.whatsapp||(A&&A.whatsapp)||''))+'"></label><label class="ck"><input type="checkbox" id="remNF"'+(l.emite_nf?' checked':'')+'><span>Emito nota fiscal<small class="hint" style="display:block;margin:0">Marque se a loja emite NF-e: ao gerar cada etiqueta, o painel pede a chave da nota. Sem nota, a etiqueta sai com declaração de conteúdo.</small></span></label><small class="hint" style="display:block">O endereço de coleta é o endereço da loja (Dados da loja).</small></details>';
 e.innerHTML=T+'<small class="hint" style="display:block;margin:2px 0 0">Verificando…</small>'+rem;
 try{const s=await rpc('me_status');MEPEND=Number(s.pendentes)||0;MECON=!!s.conectado;if(SB==='pi')setTimeout(iniR,0);e.innerHTML=T+(s.conectado?'<div class="mpok">✓ Conectado<small>'+(s.nome?esc(s.nome)+' · ':'')+'desde '+new Date(s.desde).toLocaleDateString('pt-BR')+'</small></div><small class="hint" style="display:block;margin:6px 0 8px">Nos pedidos de outras cidades, toque em <b>Gerar etiqueta</b>; o valor sai do saldo do Melhor Envio. <button type="button" class="lk" style="color:var(--red)" onclick="meDesc()">Desconectar</button></small>'
  :'<small class="hint" style="display:block;margin:4px 0 8px">Para vender para outras cidades, conecte a conta do Melhor Envio da loja e gere as etiquetas direto nos pedidos.</small><ol class="mpst"><li>Toque em <b>Conectar Melhor Envio</b>.</li><li>Entre na conta do Melhor Envio da loja (ou crie uma, é grátis).</li><li>Autorize o Eita Vale.</li><li>Coloque saldo na carteira do Melhor Envio para pagar as etiquetas.</li></ol><button type="button" class="btn" id="meBtn" onclick="meCon()">Conectar Melhor Envio</button>')+rem}
 catch(x){e.innerHTML=T+'<small class="hint" style="display:block;margin:2px 0 0">Não foi possível verificar agora.</small>'+rem}}
