 if(LJA&&LJA.emite_nf){nf=await dlg({msg:'Chave da nota fiscal deste pedido (44 números):',input:1,ph:'Chave de acesso da NF-e',ok:'Gerar etiqueta',no:'Voltar'});if(nf===null)return;nf=nf.replace(/\D/g,'');if(nf.length!==44){toast('A chave da nota fiscal tem 44 números.');return}}
 else if(!(await dlg({msg:'Gerar a etiqueta dos Correios deste pedido?\nO valor do frete sai do saldo da sua conta no Melhor Envio.',ok:'Gerar etiqueta',no:'Voltar'})))return;
