function recortarBn(file){return new Promise(ok=>{if(!file||!file.size)return ok('');const fr=new FileReader();fr.onerror=()=>ok('');fr.onload=()=>{const im=new Image();im.onerror=()=>ok('');im.onload=()=>{
 const W=1500,H=500,m=document.createElement('div');m.className='crp bnx';m.innerHTML='<h3>Ajuste o banner</h3><p>Arraste para posicionar e use o zoom. O que aparece no retângulo é o que ficará na página inicial.</p><canvas id="bcrc" width="'+W+'" height="'+H+'"></canvas><input id="bcrz" type="range" min="1" max="4" step="0.01" value="1" aria-label="Zoom"><div class="rw"><button class="btn r" id="bcrn" type="button">Cancelar</button><button class="btn" id="bcry" type="button">Usar esta imagem</button></div>';document.body.appendChild(m);
 const cv=m.querySelector('#bcrc'),cx=cv.getContext('2d'),z=m.querySelector('#bcrz'),base=Math.max(W/im.width,H/im.height);let k=1,ox=0,oy=0;
 const lim=()=>{const w=im.width*base*k,h=im.height*base*k,mx=(w-W)/2,my=(h-H)/2;ox=Math.max(-mx,Math.min(mx,ox));oy=Math.max(-my,Math.min(my,oy))};
 const draw=()=>{lim();cx.fillStyle='#fff';cx.fillRect(0,0,W,H);const w=im.width*base*k,h=im.height*base*k;cx.drawImage(im,W/2+ox-w/2,H/2+oy-h/2,w,h)};draw();
 const P=new Map();let d0=0,k0=1;
 cv.onpointerdown=e=>{cv.setPointerCapture(e.pointerId);P.set(e.pointerId,[e.clientX,e.clientY]);if(P.size===2){const a=[...P.values()];d0=Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1]);k0=k}};
 cv.onpointermove=e=>{if(!P.has(e.pointerId))return;const p=P.get(e.pointerId),r=W/cv.getBoundingClientRect().width;if(P.size===1){ox+=(e.clientX-p[0])*r;oy+=(e.clientY-p[1])*r}P.set(e.pointerId,[e.clientX,e.clientY]);if(P.size===2&&d0){const a=[...P.values()];k=Math.max(1,Math.min(4,k0*Math.hypot(a[0][0]-a[1][0],a[0][1]-a[1][1])/d0));z.value=k}draw()};
 cv.onpointerup=cv.onpointercancel=e=>{P.delete(e.pointerId);d0=0};
 cv.onwheel=e=>{e.preventDefault();k=Math.max(1,Math.min(4,k-e.deltaY/500));z.value=k;draw()};
 z.oninput=()=>{k=+z.value;draw()};
 m.querySelector('#bcrn').onclick=()=>{m.remove();ok('')};
 m.querySelector('#bcry').onclick=()=>{const u=cv.toDataURL('image/jpeg',.85);m.remove();ok(u)};
 };im.src=fr.result};fr.readAsDataURL(file)})}
