function ofRest(ms){if(ms<=0)return 'encerrada';const m=Math.floor(ms/60000),h=Math.floor(m/60);return h>=24?Math.floor(h/24)+'d '+(h%24)+'h':h?h+'h '+(m%60)+'min':m+' min'}
