async function redeDesl(id,de){const x=AD.find(y=>y.id===id)||{};document.querySelectorAll('.mdl').forEach(e=>e.remove());if(!(await dlg({msg:'Desligar '+x.nome+' ('+(x.cidade||'Sobradinho')+') das outras unidades?',ok:'Desligar',no:'Voltar'})))return;
 try{const r=x.rede;await rpc('admin_loja_rede',{p_id:id,p_rede:''});const rest=AD.filter(y=>y.rede===r&&y.id!==id);if(rest.length===1)await rpc('admin_loja_rede',{p_id:rest[0].id,p_rede:''});AD=await run('adminListar',S);admRender();carregar();toast('Unidade desligada.');lojaRede(de)}catch(e){toast(e.message)}}
async function copiarProd(id){const d=AD.find(x=>x.id===id)||{};pickLoja('📋 Copiar produtos para '+esc(d.nome),'Digite o nome da loja de onde copiar.',[id],async o=>{
 if(!(await dlg({msg:'Copiar os '+o.produtos+' produtos de '+o.nome+' ('+(o.cidade||'Sobradinho')+') para '+d.nome+'?\nCopia título, fotos, descrição, preço, categoria, tamanhos e medidas. Os produtos chegam pausados e com estoque zerado, para a loja conferir e publicar.',ok:'Copiar',no:'Voltar'})))return;
 try{const n=await rpc('admin_copiar_produtos',{p_de:o.id,p_para:id});AD=await run('adminListar',S);admRender();toast('✅ '+n+' produtos copiados para '+d.nome+'.')}catch(x){toast(x.message)}})}
async function decidir(id,acao){let motivo='';

 if(acao==='recusar'||acao==='banir'||acao==='suspender'){motivo=((await askTxtP('Motivo (será enviado ao lojista):'))||'').trim();if(!motivo)return}
 if(acao==='suspender'&&!(await dlg({msg:'Suspender esta loja? Ela e os produtos saem da vitrine e o lojista só volta com a sua autorização.',ok:'Suspender',no:'Voltar'})))return;
 if(acao==='banir'&&!(await dlg({msg:'Banir esta loja? Ela sai da vitrine.',ok:'Banir',no:'Voltar'})))return;
 say('aMsg','Salvando…');
 run('adminDecidir',S,id,acao,motivo).then(r=>{const n=r.responsavel||'';let t='';
  if(acao==='recusar')t='Olá'+(n?', '+n:'')+'! Obrigado pelo interesse no *Eita Vale*.\n\nInfelizmente o cadastro da loja *'+r.nome+'* não foi aprovado desta vez.\n\n*Motivo:* '+motivo+'\n\nVocê pode corrigir as informações e fazer um novo cadastro em *Minha loja > Cadastre sua loja*:\n'+SITE+'\n\nQualquer dúvida, é só responder esta mensagem.';
  else if(acao==='aprovar')t='Olá'+(n?', '+n:'')+'! 🎉 Sua loja *'+r.nome+'* foi *aprovada* no Eita Vale!\n\nComo começar:\n1) Acesse: '+SITE+'\n2) Toque em *Minha conta* e entre com o seu WhatsApp e a senha do cadastro\n3) Em *Loja*, confira horários, taxa de entrega por bairro e formas de pagamento\n4) Em *Produtos*, cadastre fotos, preço e estoque (roupas e calçados com os tamanhos)\n\nDica: use o botão *Oferta* (o do cacto 🌵) para vender mais com uma oferta Acaba Num Instante, e responda as perguntas dos clientes na aba *Perguntas*.\n\nQualquer dúvida, é só responder esta mensagem.';
  else if(acao==='suspender')t='Olá'+(n?', '+n:'')+'! A loja *'+r.nome+'* foi *suspensa* no Eita Vale.\n\nMotivo: '+motivo+'\n\nEnquanto estiver suspensa, ela não aparece na vitrine nem recebe pedidos novos. Para resolver, responda esta mensagem.';
  else if(acao==='banir')t='Olá'+(n?', '+n:'')+'! A loja *'+r.nome+'* foi removida do Eita Vale.\n\nMotivo: '+motivo+'\n\nPara esclarecimentos, responda esta mensagem.';
  say('aMsg','Feito. '+(t?'<br><br><a class="buy" target="_blank" rel="noopener" href="'+wa(r.whatsapp,t)+'">Avisar o lojista no WhatsApp</a>':''));
  return run('adminListar',S)}).then(l=>{AD=l;admRender();carregar()}).catch(x=>say('aMsg',esc(x.message),1))}
async function renomear(){const at=String($('lojaNome').textContent||'').trim(),ok=LST==='pendente'||LST==='recusada';
 let info='Você pode trocar o nome da loja 1 vez a cada 30 dias.';
 if(!ok&&LNA){const lib=new Date(new Date(LNA).getTime()+30*864e5);if(lib>new Date()){const f=d=>d.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'});return dlg({msg:'Você já alterou o nome em '+f(new Date(LNA))+'. A próxima troca fica liberada em '+f(lib)+'.',ok:'Entendi',cancel:false})}}
 const v=await dlg({msg:'Alterar nome da loja\n\n'+info,input:true,val:at,ok:'Salvar',ph:'Nome da loja'});if(v==null)return;const n=String(v).trim().replace(/\s+/g,' ');
 if(!n||n===at)return;if(n.length<2||n.length>80)return dlg({msg:'O nome deve ter entre 2 e 80 caracteres.',cancel:false});
 const c=await dlg({msg:'Confirmar a troca do nome para "'+n+'"?\n\nA próxima troca só fica liberada daqui a 30 dias.',ok:'Confirmar'});if(!c)return;
 try{const r=await run('renomearLoja',n);$('lojaNome').textContent=r.nome;LNA=r.nome_alterado_em||LNA;hdUser();toast('Nome da loja alterado');try{carregar&&carregar()}catch(_){}}
 catch(x){dlg({msg:x.message||'Não foi possível alterar o nome.',cancel:false})}}
async function cupTabela(){if(!CPTAB)try{CPTAB=await rpc('comissao_tabela')}catch(e){CPTAB=[]}return CPTAB}
function comTab(u){if(!(u>0))return 0;for(const b of (CPTAB||[])){if(b.ate==null||u<=+b.ate)return Math.min(u,Math.round((u*b.pct/100+(+b.fixo||0))*100)/100)}return 0}
function comRegra(u,r,p){if(!(u>0))return 0;const x=Math.round(u*(p||0))/100;return r==='fixo'?Math.min(u,x):r==='extra'?Math.min(u,comTab(u)+x):comTab(u)}
function cupSim(){const f=document.querySelector('#au form');if(!f||!$('cpsR'))return;const fd=new FormData(f),q=fd.get('quem_paga'),r=fd.get('regra_com'),fr=fd.get('tipo')==='frete';
 $('cpLp').style.display=q==='dividido'?'':'none';$('cpCp').style.display=r==='tabela'?'none':'';$('cpCpT').textContent=r==='extra'?'Extra sobre a tabela':'Comissão fixa';
 const P=num($('cpsP').value)||0,pct=num(fd.get('valor')||0)||0,teto=num(fd.get('teto')||'')||0,cp=num(fd.get('com_pct')||0)||0,s=q==='valeshop'?0:q==='dividido'?Math.min(100,Math.max(0,num(fd.get('loja_pct')||50)||0))/100:1;
 if(fr){$('cpsR').innerHTML='<p class="hint">Frete grátis: o valor do frete é dividido do mesmo jeito (a parte do Eita Vale sai da comissão do pedido).</p>';return}
 let D=Math.round(P*pct)/100;if(teto>0)D=Math.min(D,teto);D=Math.min(D,P);let C=0,vs=0,cap=false;
 for(let i=0;i<2;i++){C=comRegra(P-D*s,r,cp);vs=Math.round(D*(1-s)*100)/100;if(vs<=C+0.005||vs===0)break;cap=true;D=Math.floor(D*(C/vs)*100)/100}
 vs=Math.min(Math.round(D*(1-s)*100)/100,C);const fee=Math.max(0,Math.round((C-vs)*100)/100),cli=Math.round((P-D)*100)/100,loja=Math.round((cli-fee)*100)/100;
 $('cpsR').innerHTML='<div class="rs"><span>Cliente paga</span><b>'+brl(cli)+'</b></div><div class="rs"><span>Desconto</span><b>'+brl(D)+(s<1?' <small>(loja '+brl(D-vs)+' · Eita Vale '+brl(vs)+')</small>':'')+'</b></div><div class="rs"><span>Eita Vale fica com</span><b>'+brl(fee)+'</b></div><div class="rs"><span>Loja recebe</span><b>'+brl(loja)+'</b></div><small class="hint">Sem contar a taxa do Mercado Pago. Comissão normal deste preço: '+brl(comTab(P))+'.'+(cap?' ⚠️ O Eita Vale só cobre até a comissão: o desconto foi limitado a '+brl(D)+'.':'')+'</small>'}
const cmDt=v=>new Date(v).toLocaleString('pt-BR',{timeZone:'America/Bahia',day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'});
const cmDesc=c=>c.modo==='fixo'?(+c.desc_pct)+'% de desconto':'de '+(+c.desc_pct)+'% a '+(+c.desc_max)+'% (a loja escolhe)';
const cmFx=c=>+c.com_fixo>0?' + '+brl(+c.com_fixo)+' por item':'';const cmComL=c=>{const L=LJA||{},n=v=>String(+(+v).toFixed(2)).replace('.',',');if(L.com_modo==='isenta')return 'comissão 0% (sua loja é isenta)';if(L.com_modo==='pct'&&L.com_pct!=null){const lp=+L.com_pct;if(c.regra_com==='fixo'){const m=Math.min(+c.com_pct,lp);return 'comissão '+n(m)+'%'+(lp<+c.com_pct?' (taxa especial da sua loja)':'')}return 'comissão até '+n(lp)+'% (taxa especial da sua loja)'}return cmCom(c)};const cmCom=c=>c.regra_com==='fixo'?'comissão '+(+c.com_pct)+'%'+cmFx(c):c.regra_com==='extra'?'comissão tabela + '+(+c.com_pct)+'%'+cmFx(c):'comissão tabela normal';
let CMS=[];function cmaL(){$('ax').innerHTML='<p class="msg">Carregando…</p>';Promise.all([run('adminCampanhas'),run('adminCampanhaSaidas').catch(()=>[])]).then(([l,s])=>{CML=l;CMS=s||[];cmaR()}).catch(x=>$('ax').innerHTML='<p class="msg err">'+esc(x.message)+'</p>')}
function cmaSt(c){const a=NOW();return new Date(c.fim)<=a?'Encerrada':c.status==='rascunho'?'📝 Rascunho':c.status==='agendada'?'⏰ Lança no início':!c.ativo?'⏸ Pausada':new Date(c.inicio)>a?'Lançada · começa em breve':'No ar'}
function cmaR(){$('ax').innerHTML='<p class="hint" style="margin:10px 0">Crie uma campanha (ex.: Forró do Vaqueiro) com uma tag. As lojas escolhem os produtos no painel delas e, no período, a vitrine mostra a tag, o preço com desconto e uma aba própria.</p><button class="btn" style="margin:0 0 12px" onclick="cmaForm()">＋ Nova campanha</button>'+(CMS.length?'<div class="item cmsd"><b>⏳ Peças tiradas aguardando 4 h para voltar</b><small class="hint" style="display:block">Se a loja tirou por engano, libere para ela recolocar na hora.</small>'+CMS.map(s=>'<div class="cmsr"><span><b>'+esc(s.produto)+'</b><small>'+esc(s.loja||'')+' · '+esc(s.tag)+' · saiu às '+esc(s.saiu)+', volta às '+esc(s.volta)+'</small></span><button class="btn s" onclick="cmaLib(\''+s.campanha_id+'\',\''+s.produto_id+'\')">Liberar agora</button></div>').join('')+'</div>':'')+(CML.length?CML.map(c=>{const st=cmaSt(c);
 return '<div class="item" style="display:block'+(st==='Encerrada'||st==='⏸ Pausada'?';opacity:.7':'')+'"><div class="rs"><span>'+ctg(c,1)+' <b style="font-size:16px">'+esc(c.nome)+'</b></span><span class="st '+(st==='No ar'?'ativa':st==='Encerrada'||st==='⏸ Pausada'?'recusada':'')+'">'+st+'</span></div>'+(c.status!=='lancada'&&new Date(c.fim)>NOW()?'<small class="ctst">'+(c.teste_loja?'🧪 Em teste: só a loja <b>'+esc(c.teste_nome||'escolhida')+'</b> e você veem a campanha.':'Nenhuma loja vê esta campanha ainda. Escolha uma loja de teste em ✏️ Editar, se quiser testar.')+'</small>':'')+'<div class="cmaB"><div class="cmaI"><small>'+cmDt(c.inicio)+' até '+cmDt(c.fim)+'</small><small>'+cmDesc(c)+' · '+cmCom(c)+'</small><small>⏱ Término: '+(c.mostra_fim===false?'oculto':'visível')+' na página do produto</small><small>📍 '+cmaCidT(c)+'</small><small>'+c.itens+' produto(s) de '+c.lojas+' loja(s)</small>'+cmaRes(c)+'</div>'+cmPvH(c)+'</div>'+
 (new Date(c.fim)>NOW()&&c.status!=='lancada'?'<button class="btn cln cmaL" onclick="cmaLancar(\''+c.id+'\')">🚀 Lançar para as lojas</button>':'')+'<div class="cmaG"><button class="btn s" onclick="cmaForm(\''+c.id+'\')">✏️ Editar</button><button class="btn s" onclick="cmaItens(\''+c.id+'\')">📦 Produtos</button><button class="btn s" onclick="cmaDup(\''+c.id+'\')">📋 Duplicar</button>'+(new Date(c.fim)>NOW()?'<button class="btn s" onclick="cmaPausa(\''+c.id+'\','+(c.ativo?'true':'false')+')">'+(c.ativo?'⏸️ Pausar':'▶️ Retomar')+'</button>':'')+'</div><div id="cmi_'+c.id+'"></div>'+(new Date(c.fim)>NOW()?'<label class="cmaT"><span>⏳ Contagem na página inicial<small>'+(c.contagem?'Ligada: aparece abaixo do cartaz':'Desligada')+'</small></span><input type="checkbox" class="sw"'+(c.contagem?' checked':'')+' onchange="cmaCont(\''+c.id+'\',this.checked)"></label>':'')+'<div class="cmaX"><button class="lk" onclick="cmaDel(\''+c.id+'\')">🗑️ Excluir campanha</button></div></div>'}).join(''):'<p class="msg">Nenhuma campanha criada ainda.</p>')}
function cmaItens(id){const e=$('cmi_'+id),c=CML.find(x=>x.id===id);if(!e||!c)return;if(e.innerHTML){e.innerHTML='';return}
 e.innerHTML=c.lista.length?'<div class="cmil">'+c.lista.map(i=>'<div class="rs"><span>'+esc(i.titulo)+'<small style="display:block">'+esc(i.loja)+' · '+(+i.pct)+'% · '+brl(i.preco)+' → '+brl(Math.round(i.preco*(100-i.pct))/100)+'</small></span><button class="lk" onclick="cmaRem(\''+id+'\',\''+i.produto_id+'\')">Tirar</button></div>').join('')+'</div>':'<p class="hint">Nenhuma loja aderiu ainda.</p>'}
async function cmaLib(c,p){try{await T.adminCampanhaLiberar(c,p);toast('Liberada: a loja já pode recolocar a peça');cmaL()}catch(x){toast(x.message)}}
async function cmaRem(c,p){if(!(await dlg({msg:'Tirar este produto da campanha? Ele volta ao preço normal.',ok:'Tirar',no:'Voltar'})))return;run('adminCampanhaItemRemover',c,p).then(()=>{toast('Produto retirado');cmaL();carregar()}).catch(x=>toast(x.message))}
async function cmaDel(id){const c=CML.find(x=>x.id===id);if(!c||!(await dlg({msg:'Excluir a campanha '+c.tag+' ('+c.nome+')? Os produtos voltam ao preço normal na hora.',ok:'Excluir',no:'Voltar'})))return;run('adminCampanhaExcluir',id).then(()=>{toast('Campanha excluída');cmaL();carregar()}).catch(x=>toast(x.message))}
function cmaForm(id,dup){const c=dup||CML.find(x=>x.id===id)||{nome:'',tag:'🔥',cor:'#C0392B',modo:'fixo',desc_pct:10,desc_max:30,regra_com:'tabela',com_pct:5,com_fixo:0,tag_pos:'topo',mostra_fim:true,ativo:true,inicio:new Date().toISOString(),fim:new Date(Date.now()+7*864e5).toISOString()};CME=id||null;
 $('ax').innerHTML='<form class="item" style="display:block;margin-top:12px" oninput="cmaPrev()" onsubmit="return cmaSalvar(event)"><b>'+(id?'Editar campanha':'Nova campanha')+'</b>'+
 '<label>Nome da campanha<input name="nome" required maxlength="60" placeholder="Ex.: Forró do Vaqueiro" value="'+esc(c.nome)+'"></label>'+
 '<div style="display:flex;gap:8px"><label style="flex:2">Tag (aparece nos produtos)<input name="tag" required maxlength="16" placeholder="Ex.: 🔥FDV" value="'+esc(c.tag)+'" oninput="cmaPrev()"></label><label style="flex:1">Cor<input name="cor" type="color" value="'+esc(c.cor)+'" oninput="cmaPrev()" style="height:46px;padding:4px"></label></div><label>Onde a tag aparece na foto<select name="tag_pos" onchange="cmaPrev()"><option value="topo"'+(c.tag_pos!=='base'?' selected':'')+'>🔝 No topo da foto</option><option value="base"'+(c.tag_pos==='base'?' selected':'')+'>⬇️ Embaixo da foto (no lugar de "Última" / "Últimas 2…5")</option></select></label><label class="ck" id="cmIcW" style="margin:-2px 0 8px"><input type="checkbox" name="tag_icone"'+(c.tag_icone?' checked':'')+'><span>Mostrar a sacola pegando fogo na tag<small>Estilo Black Friday. Sem marcar, a tag mostra só o texto.</small></span></label><div id="cmPv" style="margin:-4px 0 8px"></div><label class="cmaT" style="margin:0 0 10px"><span>⏱ Mostrar quando a campanha termina<small id="cmMfP"></small></span><input type="checkbox" class="sw" name="mostra_fim"'+(c.mostra_fim!==false?' checked':'')+' onchange="cmaPrev()"></label>'+
 '<label>Começa em<input type="datetime-local" name="inicio" required value="'+isoLocal(c.inicio)+'"></label><label>Termina em<input type="datetime-local" name="fim" required value="'+isoLocal(c.fim)+'"></label>'+
 '<label>Desconto<select name="modo" onchange="cmaPrev()"><option value="fixo"'+(c.modo==='fixo'?' selected':'')+'>Fixo para todos</option><option value="minimo"'+(c.modo==='minimo'?' selected':'')+'>Mínimo (a loja pode dar mais)</option></select></label>'+
 '<div style="display:flex;gap:8px"><label style="flex:1"><span id="cmDl">Desconto (%)</span><input name="desc_pct" inputmode="decimal" required value="'+esc(String(c.desc_pct))+'"></label><label style="flex:1" id="cmMx">Máximo (%)<input name="desc_max" inputmode="decimal" value="'+esc(String(c.desc_max))+'"></label></div>'+
 '<label>Comissão nas vendas da campanha<select name="regra_com" onchange="cmaPrev()"><option value="tabela"'+(c.regra_com==='tabela'?' selected':'')+'>Tabela normal</option><option value="fixo"'+(c.regra_com==='fixo'?' selected':'')+'>Percentual fixo</option><option value="extra"'+(c.regra_com==='extra'?' selected':'')+'>Tabela normal + extra</option></select></label><div id="cmCp" style="display:flex;gap:8px"><label style="flex:1">Porcentagem (%)<input name="com_pct" inputmode="decimal" value="'+esc(String(c.com_pct||5))+'"></label><label style="flex:1">+ R$ fixo por item<input name="com_fixo" inputmode="numeric" data-rs value="'+(+c.com_fixo>0?(+c.com_fixo).toFixed(2).replace('.',','):'')+'"></label></div>'+
 cmaCidH(c)+'<label class="ck"><input type="checkbox" name="ativo"'+(c.ativo?' checked':'')+'> Campanha ativa (desmarque para deixar pausada)</label>'+(c.status==='lancada'?'':cmaTst(c))+'<div id="cmEm"></div><div style="display:flex;gap:8px"><button class="btn s">Salvar</button><button type="button" class="btn s r" onclick="cmaR()">Cancelar</button></div></form>';cmaPrev();scrollTo(0,0)}
const CMCID=['Sobradinho','Juazeiro','Petrolina','Casa Nova','Sento Sé'];
function cmaCidT(c){const cs=c.cidades||[];return cs.length?'Só '+cs.join(', '):'Todas as cidades'}
function cmaCidH(c){const cs=c.cidades||[],alg=cs.length>0;
 return '<fieldset class="cmcid"><legend>Cidades da campanha</legend><label class="ck"><input type="radio" name="cidT" value="todas"'+(alg?'':' checked')+' onchange="cmaCidV()"><span>Todas as cidades</span></label><label class="ck"><input type="radio" name="cidT" value="alg"'+(alg?' checked':'')+' onchange="cmaCidV()"><span>Só algumas cidades</span></label><div id="cmCid" style="'+(alg?'':'display:none')+'">'+CMCID.map(x=>'<label class="ck"><input type="checkbox" name="cid" value="'+x+'"'+(cs.indexOf(x)>-1?' checked':'')+'><span>'+x+'</span></label>').join('')+'<small class="hint" style="display:block">Só as lojas dessas cidades veem a campanha e são avisadas. Na vitrine, a aba e a contagem aparecem só para quem escolheu essas cidades.</small></div></fieldset>'}
function cmaCidV(){const r=document.querySelector('#ax [name=cidT]:checked'),e=$('cmCid');if(e)e.style.display=r&&r.value==='alg'?'':'none'}
function cmaPrev(){const f=document.querySelector('#ax form');if(!f)return;{const w=$('cmIcW');if(w)w.style.display=f.tag_pos.value==='base'?'':'none'}const fd=new FormData(f),ed=CME&&CML.find(x=>x.id===CME),fm=fd.get('fim');$('cmPv').innerHTML='<div class="cmaB"><div class="cmaI">Prévia: '+(fd.get('tag_pos')==='base'?'<span class="bfs" style="background:'+esc(fd.get('cor'))+'">'+(fd.get('tag_icone')?SVGP:'')+esc(String(fd.get('tag')||'TAG').toUpperCase())+'</span> <small class="hint">embaixo da foto</small>':ctg({tag:fd.get('tag')||'TAG',cor:fd.get('cor')},1)+' <small class="hint">no topo da foto</small>')+'</div>'+cmPvH({tag:fd.get('tag')||'TAG',cor:fd.get('cor'),tag_pos:fd.get('tag_pos'),tag_icone:!!fd.get('tag_icone'),mostra_fim:!!fd.get('mostra_fim'),desc_pct:num(fd.get('desc_pct'))||0,fim:fm?new Date(fm+':00-03:00').toISOString():'',lista:ed?ed.lista:[]})+'</div>';$('cmMx').style.display=fd.get('modo')==='minimo'?'':'none';{const e=$('cmMfP');if(e)e.textContent='Página do produto: '+(fd.get('nome')||'Campanha')+' · 20% OFF'+(fd.get('mostra_fim')?' · termina em 5d 12:00:00':'')}$('cmDl').textContent=fd.get('modo')==='minimo'?'Mínimo (%)':'Desconto (%)';$('cmCp').style.display=fd.get('regra_com')==='tabela'?'none':''}
