 const p={id:CME||'',nome:fd.get('nome'),tag:fd.get('tag'),cor:fd.get('cor'),inicio:iso(fd.get('inicio')),fim:iso(fd.get('fim')),modo:fd.get('modo'),desc_pct:String(num(fd.get('desc_pct'))),desc_max:String(num(fd.get('desc_max')||fd.get('desc_pct'))),regra_com:fd.get('regra_com'),com_pct:String(num(fd.get('com_pct')||0)),com_fixo:String(num(fd.get('com_fixo')||0)),tag_pos:fd.get('tag_pos')||'topo',tag_icone:fd.get('tag_pos')==='base'&&!!fd.get('tag_icone'),mostra_fim:!!fd.get('mostra_fim'),ativo:!!fd.get('ativo'),teste_loja:fd.get('teste_loja')||'',cidades:fd.get('cidT')==='alg'?fd.getAll('cid'):[]};if(fd.get('cidT')==='alg'&&!p.cidades.length){toast('Marque pelo menos uma cidade.');return false}
