// deslizar o dedo entre as abas do painel (Início · Pedidos · Produtos · Mais), como nos outros apps
(function(){const O=['pi','pd','pp','mais'];let x0=0,y0=0,t0=0,ok=false;const pg=$('painel');if(!pg||pg.dataset.sw)return;pg.dataset.sw=1;
 const bloq=el=>{for(let e=el;e&&e!==document.body;e=e.parentElement){if(/^(INPUT|TEXTAREA|SELECT)$/.test(e.tagName)||e.isContentEditable)return true;if(e.scrollWidth>e.clientWidth+2){const s=getComputedStyle(e).overflowX;if(s==='auto'||s==='scroll')return true}}return false};
 document.addEventListener('touchstart',e=>{ok=false;if(e.touches.length!==1)return;const t=e.touches[0];x0=t.clientX;y0=t.clientY;t0=Date.now();
  ok=x0>24&&x0<innerWidth-24&&pg.offsetParent!==null&&O.indexOf(SB)>=0&&!$('dwr').classList.contains('on')&&!document.querySelector('.mdl')&&!bloq(e.target)},{passive:true});
 document.addEventListener('touchend',e=>{if(!ok)return;ok=false;const t=e.changedTouches[0],dx=t.clientX-x0,dy=t.clientY-y0;
  if(Math.abs(dx)<70||Math.abs(dx)<Math.abs(dy)*1.8||Date.now()-t0>800)return;const i=O.indexOf(SB),j=i+(dx<0?1:-1);if(i<0||j<0||j>=O.length)return;
  if(O[j]==='mais'){dwr(1);return}sub(O[j]);const p=$(O[j]);if(p){p.classList.remove('swl','swr');void p.offsetWidth;p.classList.add(dx<0?'swl':'swr')}},{passive:true})})();

