function pagH(nm,v,svc){const c=svc?'na contratação':'na compra',O=[[0,'Pagamento integral '+c],[30,'30% '+c+' + 70% '],[40,'40% '+c+' + 60% '],[50,'50% '+c+' + 50% '],[60,'60% '+c+' + 40% ']],q=svc?'quando concluir o serviço':'quando ficar pronto';v=+v||0;
 return '<div class="fgrp pagg"><b>💳 Forma de pagamento'+(svc?' do serviço':' da encomenda')+'</b>'+O.map(o=>'<label class="pago"><input type="radio" name="'+nm+'" value="'+o[0]+'"'+(o[0]===v?' checked':'')+'><span>'+o[1]+(o[0]?q:'')+(o[0]===50?' <i class="pagrc">RECOMENDADO</i>':'')+'</span></label>').join('')+
 '<small class="pagrec">⭐ <b>Pagamento em 2 partes é mais seguro para você e para o cliente.</b> O sinal cobre o material e a produção; o cliente paga o restante só '+(svc?'quando o serviço for concluído':'quando a encomenda ficar pronta')+'. Se ele desistir depois de pagar o sinal, o sinal fica com você como indenização. A comissão é dividida na mesma proporção.</small></div>'}
