 if(p.pg_status!=='pago')return '<div class="ocS"><b>💳 Pagamento em 2 partes · sinal de '+p.sinal_pct+'%</b><small>O cliente paga agora '+brl(p.sinal)+' e o restante ('+brl(p.rest)+(+p.frete?', com o frete':'')+') quando '+(sv?'o serviço for concluído':'ficar pronto')+'.</small></div>';
