// quase quadrada: corta o centro; muito comprida ou larga: encaixa inteira sobre um fundo desfocado da própria foto
function reduzirQ(file,m,q){return new Promise(ok=>{if(!file||!file.size)return ok('');const r=new FileReader();r.onerror=()=>ok('');r.onload=()=>{const i=new Image();i.onerror=()=>ok('');i.onload=()=>{
 const w=i.width,h=i.height,ar=w/h,S=Math.min(m||900,Math.max(w,h)),c=document.createElement('canvas');c.width=c.height=S;const x=c.getContext('2d');
 if(ar>=0.8&&ar<=1.25){const s=Math.min(w,h);x.drawImage(i,(w-s)/2,(h-s)/2,s,s,0,0,S,S)}
 else{const k=Math.max(S/w,S/h);x.filter='blur(24px) brightness(1.08)';x.drawImage(i,(S-w*k)/2,(S-h*k)/2,w*k,h*k);x.filter='none';x.fillStyle='rgba(255,255,255,.35)';x.fillRect(0,0,S,S);const k2=Math.min(S/w,S/h);x.drawImage(i,(S-w*k2)/2,(S-h*k2)/2,w*k2,h*k2)}
 ok(c.toDataURL('image/jpeg',q||.72))};i.src=r.result};r.readAsDataURL(file)})}

